<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Allinpay/discount')}" class="on">指定卡bin</a>|				</ul>			</div>            <table class="search_table" width="100%">                <tr>                    <td style="width:60%;">                        <form action="{pigcms{:U('Allinpay/card', array('id' => $did))}" method="get">                            <input type="hidden" name="c" value="Allinpay"/>                            <input type="hidden" name="a" value="card"/>                            <input type="hidden" name="id" value="{pigcms{$did}"/>                            <select name="status">                                <option value="0" <if condition="$status eq 0">selected="selected"</if>>全部</option>                                <option value="1" <if condition="$status eq 1">selected="selected"</if>>已上线</option>                                <option value="2" <if condition="$status eq 2">selected="selected"</if>>未上线</option>                            </select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                            <select name="searchtype">                                <option value="cardbin" <if condition="$_GET['searchtype'] eq 'cardbin'">selected="selected"</if>>银行卡bin</option>                                <option value="bankname" <if condition="$_GET['searchtype'] eq 'bankname'">selected="selected"</if>>银行名称</option>                                <option value="cardname" <if condition="$_GET['searchtype'] eq 'cardname'">selected="selected"</if>>银行卡名</option>                            </select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                            <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                            <input type="submit" value="查询" class="button"/>                            <input type="button" value="批量上线" id="online" class="button"/>&nbsp;&nbsp;&nbsp;&nbsp;                            <input type="button" value="批量下线" id="offline" class="button"/>&nbsp;&nbsp;&nbsp;&nbsp;                        </form>                    </td>                </tr>            </table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>								<th><input type="checkbox" id="all"></th>								<th>编号</th>								<th>银行名称</th>								<th>银行卡名称</th>								<th>银行卡bin</th>								<th>操作</th>							</tr>						</thead>						<tbody>							<if condition="count($cardList) gt 0">								<volist name="cardList" id="vo">									<tr>										<td><input type="checkbox" name="cardIds[]" value="{pigcms{$vo.cardbin}" <if condition="!empty($vo['did'])">checked</if>></td>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.bankname}</td>										<td>{pigcms{$vo.cardname}</td>										<td>{pigcms{$vo.cardbin}</td>										<td class="textcenter" data-id="{pigcms{$vo.cardbin}">                                        <span class="cb-enable"><label class="cb-enable <if condition="!empty($vo['did'])">selected</if>"><span>已上线</span><input type="radio" name="selectCard{pigcms{$vo['cardbin']}" value="1" <if condition="!empty($vo['did'])">checked="checked"</if> /></label></span>                                        <span class="cb-disable"><label class="cb-disable <if condition="empty($vo['did'])">selected</if>"><span>未上线</span><input type="radio" name="selectCard{pigcms{$vo['cardbin']}" value="0" <if condition="empty($vo['did'])">checked="checked"</if>/></label></span>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><script type="text/javascript">$(document).ready(function(){    $('#all').click(function(){        if ($(this).is(':checked')) {            $('input[type="checkbox"]').attr('checked', true);        } else {            $('input[type="checkbox"]').attr('checked', false);        }    });    var did = '{pigcms{$did}';    $('input[type="radio"]').click(function(){        var cardIds = [], mer_id = $(this).parents('td').data('id'), obj = $(this).parents('tr').find('input[type="checkbox"]');        var type = $(this).val();        cardIds.push(mer_id);        $.post('{pigcms{:U("Allinpay/changeCard")}', {'did':did, 'type':type,'cardIds':cardIds}, function(res){            if (res.status == 1) {                if (type == 1) {                    obj.attr('checked', true);                } else {                    obj.attr('checked', false);                }            } else {                alert(res.info);            }        }, 'json');    });    $('#online').click(function(){        var cardIds = [];        $("input[name='cardIds[]']:checked").each(function(){            cardIds.push($(this).val());        });        $.post('{pigcms{:U("Allinpay/changeCard")}', {'did':did, 'type':1,'cardIds':cardIds}, function(res){            if (res.status == 1) {                location.reload();            } else {                alert(res.info);            }        }, 'json');    });    $('#offline').click(function(){        var cardIds = [];        $("input[name='cardIds[]']:checked").each(function(){            cardIds.push($(this).val());        });        $.post('{pigcms{:U("Allinpay/changeCard")}', {'did':did, 'type':0,'cardIds':cardIds}, function(res){            if (res.status == 1) {                location.reload();            } else {                alert(res.info);            }        }, 'json');    });    });</script><include file="Public:footer"/>